/* ============================================
   ORG CHART
   Nested lists drawn top down: each item is a
   card with its reports in a row beneath it.
   The lines are borders on pseudo-elements on
   --color-divider: a stem down from a card, a
   rail across its reports and a stem up into
   each, so the chart needs no measuring. The
   rail stops at the first and last report's
   centres, on logical sides, so it mirrors in a
   right-to-left context.
   ============================================ */

/* Base */
.ds-org-chart {
  min-width: 0;
}

.ds-org-chart__scroll {
  overflow-x: auto;
  padding-block: var(--padding-200);
}

.ds-org-chart__tree,
.ds-org-chart__reports {
  display: flex;
  justify-content: center;
  margin: 0;
  padding: 0;
  list-style: none;
}

.ds-org-chart__tree {
  min-width: max-content;
}

/* The reports sit a gap below their manager, with a stem down from it. */
.ds-org-chart__reports {
  position: relative;
  padding-block-start: var(--gap-500);
}

.ds-org-chart__reports::before {
  content: '';
  position: absolute;
  inset-block-start: 0;
  inset-inline-start: 50%;
  block-size: calc(var(--gap-500) / 2);
  border-inline-start: var(--border-025) solid var(--color-divider);
}

/* Items */
.ds-org-chart__item {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  padding-inline: var(--padding-200);
}

/* Inside a list of reports: a stem up from each card to the rail, and the
   rail across the item, cut back to the centre at either end of the row. */
.ds-org-chart__reports > .ds-org-chart__item::before,
.ds-org-chart__reports > .ds-org-chart__item::after {
  content: '';
  position: absolute;
  inset-block-start: calc(var(--gap-500) / -2);
}

.ds-org-chart__reports > .ds-org-chart__item::before {
  inset-inline-start: 50%;
  block-size: calc(var(--gap-500) / 2);
  border-inline-start: var(--border-025) solid var(--color-divider);
}

.ds-org-chart__reports > .ds-org-chart__item::after {
  inset-inline: 0;
  border-block-start: var(--border-025) solid var(--color-divider);
}

.ds-org-chart__reports > .ds-org-chart__item:first-child::after {
  inset-inline-start: 50%;
}

.ds-org-chart__reports > .ds-org-chart__item:last-child::after {
  inset-inline-end: 50%;
}

.ds-org-chart__reports > .ds-org-chart__item:only-child::after {
  display: none;
}

/* The card: the Widget tile's edge on the primary container. */
.ds-org-chart__card {
  display: flex;
  align-items: center;
  gap: var(--gap-200);
  min-width: 0;
  padding: var(--padding-200) var(--padding-300);
  background-color: var(--color-bg-container-primary);
  border: var(--border-025) solid var(--color-bg-container-border);
  border-radius: var(--radius-300);
  white-space: nowrap;
}

.ds-org-chart__text {
  display: flex;
  flex-direction: column;
  min-width: 0;
}

.ds-org-chart__name {
  font-family: var(--font-paragraph-sm-emphasis-family);
  font-size: var(--font-paragraph-sm-emphasis-size);
  font-weight: var(--font-paragraph-sm-emphasis-weight);
  line-height: var(--font-paragraph-sm-emphasis-line-height);
  letter-spacing: var(--font-paragraph-sm-emphasis-letter-spacing);
  color: var(--color-text-primary);
}

.ds-org-chart__name--link {
  text-decoration: none;
  border-radius: var(--radius-100);
}

.ds-org-chart__name--link:hover,
.ds-org-chart__name--link:focus-visible {
  text-decoration: underline;
}

.ds-org-chart__name--link:focus-visible {
  outline: 2px solid var(--color-action-primary-bg);
  outline-offset: 2px;
}

.ds-org-chart__role {
  font-family: var(--font-caption-family);
  font-size: var(--font-caption-size);
  font-weight: var(--font-caption-weight);
  line-height: var(--font-caption-line-height);
  letter-spacing: var(--font-caption-letter-spacing);
  color: var(--color-text-tertiary);
}

import React from 'react';
import type { LinkComponent } from '../../behaviors/LinkProvider';
import { ScrollRegion } from '../../behaviors/ScrollRegion';
import { Avatar } from '../Avatar/Avatar';
import './OrgChart.css';

/** One person in the chart, and the people who report to them. */
export interface OrgChartNode {
  /** A stable id for the person. */
  id: string;
  /** Their name. */
  name: string;
  /** Their role ("Head of design"). */
  role?: string;
  /** An image for their avatar; their initials show without one. */
  avatarSrc?: string;
  /** Makes the person's name a link to their profile. */
  href?: string;
  /** The people who report to them, in order. */
  reports?: OrgChartNode[];
}

/** Props owned by OrgChart itself; everything else falls through to the root `<div>`. */
type OrgChartOwnProps = {
  /** The person at the top, with everyone under them. */
  root: OrgChartNode;
  /** The chart's name, read before the people in it ("Design team"). */
  label: string;
  /**
   * The component the people's links render with, such as Next.js's `Link`,
   * so they navigate through the app's router; a plain `<a>` when unset.
   * This component can render on the server, so it never reads a
   * LinkProvider: pass the prop even under one.
   */
  linkComponent?: LinkComponent;
  /** Additional CSS classes */
  className?: string;
};

export interface OrgChartProps extends OrgChartOwnProps, Omit<React.ComponentPropsWithRef<'div'>, keyof OrgChartOwnProps | 'children'> {}

/**
 * Who reports to whom: each person a card with their avatar, name and role,
 * their reports in a row beneath them, joined by lines. The hierarchy is
 * nested lists, so a screen reader hears each person's reports as a list
 * inside their item, at its level. A chart wider than its column scrolls
 * sideways. Server-renderable.
 */
export function OrgChart({ root, label, linkComponent, className = '', ref, ...rest }: OrgChartProps) {
  const Link = linkComponent ?? 'a';
  const node = (person: OrgChartNode): React.ReactNode => {
    const reports = person.reports ?? [];
    return (
      <li key={person.id} className="ds-org-chart__item">
        <div className="ds-org-chart__card">
          <Avatar name={person.name} src={person.avatarSrc} size="sm" aria-hidden="true" />
          <span className="ds-org-chart__text">
            {person.href !== undefined ? (
              <Link href={person.href} className="ds-org-chart__name ds-org-chart__name--link">
                {person.name}
              </Link>
            ) : (
              <span className="ds-org-chart__name">{person.name}</span>
            )}
            {person.role && <span className="ds-org-chart__role">{person.role}</span>}
          </span>
        </div>
        {reports.length > 0 && <ul className="ds-org-chart__reports">{reports.map(node)}</ul>}
      </li>
    );
  };
  const classes = ['ds-org-chart', className].filter(Boolean).join(' ');
  return (
    <div role="group" aria-label={label} {...rest} ref={ref} className={classes}>
      <ScrollRegion className="ds-org-chart__scroll">
        <ul className="ds-org-chart__tree">{node(root)}</ul>
      </ScrollRegion>
    </div>
  );
}
